const paymentHistory = `-- name: PaymentHistory :many
SELECT id, payment_id, from_status, to_status, source, provider_event_id, created_at FROM payment_status_history WHERE payment_id = $1 ORDER BY id
`

func (q *Queries) PaymentHistory(ctx context.Context, paymentID string) ([]PaymentStatusHistory, error) {
	rows, err := q.db.Query(ctx, paymentHistory, paymentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PaymentStatusHistory{}
	for rows.Next() {
		var i PaymentStatusHistory
		if err := rows.Scan(
			&i.ID,
			&i.PaymentID,
			&i.FromStatus,
			&i.ToStatus,
			&i.Source,
			&i.ProviderEventID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

