const upsertPaymentMethod = `-- name: UpsertPaymentMethod :one

INSERT INTO payment_methods (customer_id, provider, provider_ref, label)
VALUES ($1, $2, $3, $4)
ON CONFLICT (provider, provider_ref) DO UPDATE SET label = excluded.label, status = 'active', updated_at = now()
RETURNING id, customer_id, provider, provider_ref, label, status, created_at, updated_at
`

type UpsertPaymentMethodParams struct {
	CustomerID  string
	Provider    string
	ProviderRef string
	Label       string
}

// ---------------------------------------------------------------- payment methods
func (q *Queries) UpsertPaymentMethod(ctx context.Context, arg UpsertPaymentMethodParams) (PaymentMethod, error) {
	row := q.db.QueryRow(ctx, upsertPaymentMethod,
		arg.CustomerID,
		arg.Provider,
		arg.ProviderRef,
		arg.Label,
	)
	var i PaymentMethod
	err := row.Scan(
		&i.ID,
		&i.CustomerID,
		&i.Provider,
		&i.ProviderRef,
		&i.Label,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
